const order = $input.first().json.body;

const firstName   = order.customer?.first_name || order.billing_address?.first_name || 'Valued Customer';
const email       = order.email || order.customer?.email || '';
const lineItems   = Array.isArray(order.line_items) ? order.line_items : [];

const bookTitles  = lineItems.map(i => i.title).filter(Boolean);
const primaryBook = bookTitles[0] || 'your recent purchase';
const bookList    = bookTitles.join(', ');

const orderNumber = order.order_number || order.name || order.id || '';
const orderTotal  = order.total_price ? '₹' + parseFloat(order.total_price).toFixed(2) : '';

const rawPhone = order.customer?.phone || order.billing_address?.phone || order.shipping_address?.phone || '';
const phone    = rawPhone.replace(/[^0-9]/g, '').replace(/^0+/, '');
const waPhone  = phone.startsWith('91') ? phone : (phone.length === 10 ? '91' + phone : phone);

return [{ json: { firstName, email, primaryBook, bookList, bookTitles, orderNumber, orderTotal, waPhone } }];

const order = $('Extract Order Details').first().json;

const raw = $input.first().json;

let products = [];
if (Array.isArray(raw)) {
  products = raw;
} else if (raw.products && Array.isArray(raw.products)) {
  products = raw.products;
} else {
  products = $input.all().map(i => i.json).filter(p => p.title && p.handle);
}

const catalogLines = products
  .filter(p => p.title && p.handle)
  .map((p, i) => `${i + 1}. ${p.title} by ${p.vendor || 'Unknown'} (handle: ${p.handle})`);

const catalogString = catalogLines.join(' | ');

return [{ json: { ...order, catalogString, totalProducts: catalogLines.length } }];

