const order  = $('Build Catalog for AI').first().json;
const aiRaw  = $input.first().json;

// Parse AI JSON response
let recs = [];
try {
  const content = aiRaw.choices?.[0]?.message?.content || '[]';
  const cleaned = content.replace(/```json|```/g, '').trim();
  recs = JSON.parse(cleaned);
} catch(e) {
  recs = [];
}

if (!Array.isArray(recs) || recs.length === 0) {
  recs = [{ title: 'Explore Our Collection', author: '', description: 'Browse our full curated collection of books across all genres.', handle: '' }];
}

const recRows = recs.slice(0, 3).map((r, i) => {
  const url = r.handle
    ? `https://yellowfeatherbookstore.in/products/${r.handle}`
    : 'https://yellowfeatherbookstore.in';
  const authorLine = r.author ? `<div style="font-size:13px;color:#888;margin-bottom:6px;">by ${r.author}</div>` : '';
  return `<tr><td style="padding:20px 0;border-bottom:1px solid #e5e0d8;"><div style="font-size:13px;color:#C9922A;font-weight:700;margin-bottom:4px;">0${i+1}</div><div style="font-size:16px;font-weight:700;color:#1a1a2e;margin-bottom:2px;">${r.title}</div>${authorLine}<div style="font-size:14px;color:#555;line-height:1.6;margin-bottom:10px;">${r.description}</div><a href="${url}" style="display:inline-block;background:#C9922A;color:#fff;font-size:13px;font-weight:600;padding:8px 18px;border-radius:6px;text-decoration:none;">View Book &rarr;</a></td></tr>`;
}).join('');

const html = `<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"/><meta name="viewport" content="width=device-width,initial-scale=1"/><style>body{font-family:Arial,sans-serif;background:#f4f4f4;margin:0;padding:0;}.wrapper{max-width:620px;margin:32px auto;background:#fff;border-radius:10px;overflow:hidden;box-shadow:0 2px 16px rgba(0,0,0,0.10);}.header{background:#1a1a2e;padding:28px 40px;text-align:center;}.header img{height:52px;object-fit:contain;}.body{padding:40px;}p{font-size:15px;color:#444;line-height:1.8;margin:0 0 16px;}.footer{background:#f5f0e8;padding:20px 40px;font-size:13px;color:#555;line-height:1.8;border-top:1px solid #e5e0d8;}.footer strong{color:#1a1a2e;display:block;font-size:15px;margin-bottom:4px;}.footer a{color:#C9922A;text-decoration:none;}</style></head><body><div class="wrapper"><div class="header"><img src="https://yellowfeather.netlify.app/logo-landscape.png" alt="Yellow Feather Books"/></div><div class="body"><p>Hello <strong>${order.firstName}</strong>,</p><p>I hope this message finds you well! I wanted to take a moment to express my heartfelt gratitude for your recent purchase of <strong>&ldquo;${order.primaryBook}&rdquo;</strong> from Yellow Feather Books. We truly appreciate your support and trust in our bookstore.</p><p>As a token of our appreciation, I&rsquo;ve handpicked a few book recommendations from our store that I believe you&rsquo;ll enjoy:</p><table style="width:100%;border-collapse:collapse;margin:8px 0 24px;">${recRows}</table><p>I hope you find these titles intriguing and that they add to your reading journey. Thank you once again for choosing Yellow Feather Books. If you have any questions or need further assistance, please feel free to reach out to me directly!</p><p style="margin-top:28px;">Warm regards,</p></div><div class="footer"><strong>Mehru</strong><br/>Sales Manager<br/>Yellow Feather Books<br/>Phone: <a href="tel:9400448000">9400448000</a><br/>Website: <a href="https://yellowfeatherbookstore.in">https://yellowfeatherbookstore.in</a></div></div></body></html>`;

return [{ json: { ...order, emailHtml: html } }];

